import test from 'ava';
import type { S3Client } from '@aws-sdk/client-s3';
import { AwsSdkS3StorageDriverClient } from '../aws-sdk-client';

function fakeS3Client(send: (command: unknown) => Promise<unknown>, region?: string): S3Client {
  return { send, config: { region } } as unknown as S3Client;
}

test('objectExists maps a NotFound error to false', async (t) => {
  const client = new AwsSdkS3StorageDriverClient(
    fakeS3Client(() => Promise.reject(Object.assign(new Error('not found'), { name: 'NotFound' })))
  );
  t.false(await client.objectExists('b', 'k'));
});

test('objectExists maps a 404 status to false', async (t) => {
  const client = new AwsSdkS3StorageDriverClient(
    fakeS3Client(() => Promise.reject(Object.assign(new Error('nope'), { $metadata: { httpStatusCode: 404 } })))
  );
  t.false(await client.objectExists('b', 'k'));
});

test('objectExists rethrows non-404 errors', async (t) => {
  const client = new AwsSdkS3StorageDriverClient(
    fakeS3Client(() => Promise.reject(Object.assign(new Error('denied'), { $metadata: { httpStatusCode: 403 } })))
  );
  await t.throwsAsync(() => client.objectExists('b', 'k'), { message: 'denied' });
});

test('objectExists returns true when the head succeeds', async (t) => {
  const client = new AwsSdkS3StorageDriverClient(fakeS3Client(() => Promise.resolve({})));
  t.true(await client.objectExists('b', 'k'));
});

test('getObject reads the response body as bytes', async (t) => {
  const bytes = new Uint8Array([1, 2, 3]);
  const client = new AwsSdkS3StorageDriverClient(
    fakeS3Client(() => Promise.resolve({ Body: { transformToByteArray: async () => bytes } }))
  );
  t.deepEqual(await client.getObject('b', 'k'), bytes);
});

test('getObject throws when the response has no body', async (t) => {
  const client = new AwsSdkS3StorageDriverClient(fakeS3Client(() => Promise.resolve({})));
  await t.throwsAsync(() => client.getObject('b', 'k'), { message: /empty body/ });
});

test('describe surfaces a plain-string region', (t) => {
  const client = new AwsSdkS3StorageDriverClient(fakeS3Client(() => Promise.resolve({}), 'us-west-2'));
  t.deepEqual(client.describe?.(), { clientRegion: 'us-west-2' });
});

import test from 'ava';
import type { Storage } from '@google-cloud/storage';
import { GoogleCloudGcsStorageDriverClient } from '../google-cloud-client';

interface FakeFile {
  save?: (data: Uint8Array, options?: unknown) => Promise<void>;
  download?: () => Promise<[Buffer]>;
}

/** Minimal Storage stand-in: only `bucket().file()`, `save`/`download`, and `projectId` are exercised. */
function fakeStorage(file: FakeFile, projectId?: string): Storage {
  return { projectId, bucket: () => ({ file: () => file }) } as unknown as Storage;
}

test('save uploads with an ifGenerationMatch: 0 precondition', async (t) => {
  let received: unknown;
  const client = new GoogleCloudGcsStorageDriverClient(
    fakeStorage({
      save: async (_data, options) => {
        received = options;
      },
    })
  );

  await client.save('b', 'o', new Uint8Array([1, 2, 3]));

  t.deepEqual(received, { preconditionOpts: { ifGenerationMatch: 0 } });
});

test('save treats a 412 precondition failure as a successful no-op', async (t) => {
  const client = new GoogleCloudGcsStorageDriverClient(
    fakeStorage({
      save: async () => {
        throw Object.assign(new Error('precondition failed'), { code: 412 });
      },
    })
  );

  await t.notThrowsAsync(() => client.save('b', 'o', new Uint8Array([1])));
});

test('save rethrows non-412 errors', async (t) => {
  const client = new GoogleCloudGcsStorageDriverClient(
    fakeStorage({
      save: async () => {
        throw Object.assign(new Error('denied'), { code: 403 });
      },
    })
  );

  await t.throwsAsync(() => client.save('b', 'o', new Uint8Array([1])), { message: 'denied' });
});

test('download resolves the stored bytes', async (t) => {
  const bytes = Buffer.from([1, 2, 3]);
  const client = new GoogleCloudGcsStorageDriverClient(fakeStorage({ download: async () => [bytes] }));

  t.deepEqual(await client.download('b', 'o'), bytes);
});

test('an already-aborted signal short-circuits before issuing the request', async (t) => {
  let saveCalled = false;
  const client = new GoogleCloudGcsStorageDriverClient(
    fakeStorage({
      save: async () => {
        saveCalled = true;
      },
    })
  );

  await t.throwsAsync(() => client.save('b', 'o', new Uint8Array([1]), { abortSignal: AbortSignal.abort() }), {
    name: 'AbortError',
  });
  t.false(saveCalled);
});

test('describe surfaces the project ID when available', (t) => {
  const client = new GoogleCloudGcsStorageDriverClient(fakeStorage({}, 'my-project'));
  t.deepEqual(client.describe(), { projectId: 'my-project' });
});

test('describe omits the project ID when unavailable', (t) => {
  const client = new GoogleCloudGcsStorageDriverClient(fakeStorage({}));
  t.deepEqual(client.describe(), {});
});

